// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);

        // First, call SetMinSum to change MinSum (in modified version, this changes it; in reference, it reverts because intitalized is false)
        vm.prank(address(0xdead));
        bool ok;
        try c.SetMinSum(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, SetMinSum reverts (ok = false); in modified, it succeeds (ok = true).
        // We have not initialized, but in reference SetMinSum guarded. Now let's initialize.
        c.Initialized();

        // Alice deposits 0.5 ether
        vm.prank(alice);
        c.Deposit{value: 0.5 ether}();

        // Now try to collect 0.5 ether: in reference, MinSum is still 1 ether, so condition fails; in modified, MinSum is 0, so condition passes.
        vm.prank(alice);
        bool collectOk;
        try c.Collect(0.5 ether) {
            collectOk = true;
        } catch {
            collectOk = false;
        }
        // Reference: Collect reverts (false). Modified: Collect returns true.
        assertTrue(collectOk == true);
    }
}

